@import url('https://fonts.googleapis.com/css2?family=Comfortaa:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* McDonald's DNA — golden arches yellow, happy meal red */
.theme-mcdonalds-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.980 0.024 88.2);
  --surface-2: oklch(0.954 0.043 89.4);
  --fg: oklch(0.281 0 0);
  --fg-muted: oklch(0.542 0 0);
  --accent: oklch(0.575 0.213 29.6);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.857 0.165 86.5);
  --line: oklch(0.922 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 1rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Comfortaa", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-mcdonalds-dna h1,
.theme-mcdonalds-dna h2,
.theme-mcdonalds-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-mcdonalds-dna { --font-ui: var(--font-display); }
.theme-mcdonalds-dna h1 { font-weight: 700; color: var(--accent); }
.theme-mcdonalds-dna button { font-weight: 700; }

/* depth */
.theme-mcdonalds-dna thead th { background: var(--accent-2); color: oklch(0.28 0.05 60); font-weight: 700; font-size: 0.78rem; }
.theme-mcdonalds-dna td { border-bottom: 1px solid var(--line); }
.theme-mcdonalds-dna tbody tr:hover { background: var(--surface); }
.theme-mcdonalds-dna input, .theme-mcdonalds-dna select, .theme-mcdonalds-dna textarea { border: 2px solid var(--line); border-radius: var(--radius); background: oklch(1 0 0); transition: border-color 140ms ease, box-shadow 140ms ease; }
.theme-mcdonalds-dna input:focus-visible, .theme-mcdonalds-dna select:focus-visible, .theme-mcdonalds-dna textarea:focus-visible { outline: none; border-color: var(--accent-2); box-shadow: 0 0 0 3px color-mix(in oklab, var(--accent-2) 45%, transparent); }
.theme-mcdonalds-dna a { color: var(--accent); font-weight: 600; text-decoration: none; }
.theme-mcdonalds-dna a:hover { text-decoration: underline; text-decoration-color: var(--accent-2); text-decoration-thickness: 3px; text-underline-offset: 3px; }
.theme-mcdonalds-dna ::selection { background: var(--accent-2); color: oklch(0.28 0.05 60); }
.theme-mcdonalds-dna ::-webkit-scrollbar { width: 12px; }
.theme-mcdonalds-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-mcdonalds-dna ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 999px; border: 3px solid var(--surface); }
.theme-mcdonalds-dna kbd { font-family: var(--font-display); font-size: 0.72em; font-weight: 700; background: var(--accent-2); color: oklch(0.28 0.05 60); border-bottom: 3px solid var(--accent); border-radius: 0.5em; padding: 0.1em 0.5em; }
.theme-mcdonalds-dna .label-caps { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; color: var(--accent); }
.theme-mcdonalds-dna .themed-border { border-color: var(--accent-2); }
.theme-mcdonalds-dna h2::after { content: ""; display: block; width: 3rem; height: 4px; margin-top: 0.4rem; background: var(--accent-2); border-radius: 999px; }
.theme-mcdonalds-dna button:hover { transform: translateY(-1px); box-shadow: var(--shadow-2); }

/* alt mode: late-night drive-thru — warm black menu board, arches glowing */
.theme-mcdonalds-dna.alt-mode {
  --bg: oklch(0.165 0.010 60.0);
  --surface: oklch(0.205 0.014 70.0);
  --surface-2: oklch(0.250 0.020 80.0);
  --fg: oklch(0.960 0.015 90);
  --fg-muted: oklch(0.72 0.020 80);
  --accent: oklch(0.630 0.210 29.6);
  --line: oklch(1 0 0 / 14%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent-2) 55%, transparent);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%), 0 0 40px -10px oklch(0.857 0.165 86.5 / 25%);
}
.theme-mcdonalds-dna.alt-mode h1 { color: var(--accent-2); }
.theme-mcdonalds-dna.alt-mode input, .theme-mcdonalds-dna.alt-mode select, .theme-mcdonalds-dna.alt-mode textarea { background: var(--surface); color: var(--fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
